def canon_box_to_mm(box, fov_w, fov_h):
    """(x0, y0, x1, y1) on the canonical 224 grid -> mm from the frame centre (x by the width FOV, y by the height FOV)."""
    x0, y0, x1, y1 = box
    return ((x0 / K.CANON - 0.5) * fov_w, (y0 / K.CANON - 0.5) * fov_h, (x1 / K.CANON - 0.5) * fov_w, (y1 / K.CANON - 0.5) * fov_h)


def mm_box_to_canon(box_mm, fov_w, fov_h, clip=True):
    """mm from the frame centre -> canonical 224 edge coordinates; clipped to the frame (0..224) when `clip`."""
    x0, y0, x1, y1 = box_mm
    b = [(x0 / fov_w + 0.5) * K.CANON, (y0 / fov_h + 0.5) * K.CANON, (x1 / fov_w + 0.5) * K.CANON, (y1 / fov_h + 0.5) * K.CANON]
    return tuple(min(max(v, 0.0), K.CANON) for v in b) if clip else tuple(b)

