def slice_picks_notcht(lo_i, hi_i, n, min_slices):
    """ADR-113 2-B: X_notch's range indices lo_i..hi_i once each; > N_OUT -> round(linspace(lo_i, hi_i, N_OUT)); < min_slices -> widened one
    slice at a time, the lower side first then the upper side (p50's slice_picks loop), until min_slices or the series' ends."""
    n_real = hi_i - lo_i + 1
    widened = 0
    while hi_i - lo_i + 1 < min_slices:
        moved = False
        if lo_i > 0:
            lo_i -= 1; moved = True; widened += 1
        if hi_i - lo_i + 1 < min_slices and hi_i < n - 1:
            hi_i += 1; moved = True; widened += 1
        if not moved:
            break
    real = list(range(lo_i, hi_i + 1))
    if len(real) > N_OUT:
        picks = [int(v) for v in np.round(np.linspace(lo_i, hi_i, N_OUT)).astype(int)]
        assert len(set(picks)) == N_OUT, picks
    else:
        picks = real
    return picks, {"lo_i_after": lo_i, "hi_i_after": hi_i, "n_real_in_range": n_real, "widened_by": widened, "n_picks": len(picks)}

