def tile_square_mm(centre, side):
    """The square of side `side` mm centred at `centre` (mm), as an edge box (x0, y0, x1, y1)."""
    gx, gy = centre
    h = side / 2.0
    return (gx - h, gy - h, gx + h, gy + h)


def tile_canon(square_mm, fov_w, fov_h):
    """mm -> canonical 224 edge coordinates by the series' FOV (p18_17_frames.mm_box_to_canon), NOT clipped to the frame."""
    return F.mm_box_to_canon(square_mm, fov_w, fov_h, clip=False)


def cut_padded(a, r0, r1, c0, c1):
    """The native rows r0:r1 x columns c0:c1 of the normalised frame `a`, the part outside the frame black (0)."""
    H, W = a.shape
    out = np.zeros((r1 - r0, c1 - c0), np.float32)
    rr0, rr1, cc0, cc1 = max(r0, 0), min(r1, H), max(c0, 0), min(c1, W)
    if rr1 > rr0 and cc1 > cc0:
        out[rr0 - r0: rr1 - r0, cc0 - c0: cc1 - c0] = a[rr0:rr1, cc0:cc1]
    return out

