def picks_for(n, rng):
    clo, chi = rng
    lo_i = int(np.round(clo / (NS - 1) * (n - 1)))
    hi_i = int(np.round(chi / (NS - 1) * (n - 1)))
    return lo_i, hi_i, np.round(np.linspace(lo_i, hi_i, N_OUT)).astype(int)


def decode_norm(path):
    """d5's per-slice normalisation on the FULL native frame (p18_render._normalise_full_frame on the raw pixel_array)."""
    import pydicom
    return R._normalise_full_frame(pydicom.dcmread(path).pixel_array)


def crop_render(a, box_canon, right):
    """p18_render.render_native_box's body after its decode: canonical box -> native -> outward pixel bounds -> crop -> 336 square."""
    H, W = a.shape
    bn = R.canon_box_to_native(box_canon, W, H, right, "sagittal")
    r0, r1, c0, c1 = R.box_to_pixel_bounds(bn, W, H)
    out = R._to_square(a[r0:r1, c0:c1], SIZE)
    q = np.rint(out * 255.0).astype(np.uint8)
    assert np.array_equal(q.astype(np.float32) / 255.0, out), "the stored uint8 is not the rendered value"
    return q


def build_one(sid, right, geo):
    files, se = ordered(sid)
    vols = {reg: np.zeros((N_OUT, SIZE, SIZE), np.uint8) for reg in geo}
    masks = {reg: np.zeros(N_OUT, np.uint8) for reg in geo}
    rec = {"series": se, "n": 0, "failed": 0, "error": None, "regions": {}}
    if files is None:
        rec["error"] = "no stack"
        return vols, masks, rec
    canon = files[::-1] if right else files
    n = len(canon)
    rec["n"] = n
    plan = {reg: picks_for(n, g["range"]) for reg, g in geo.items()}
    need = sorted({int(i) for _, _, p in plan.values() for i in p})
    dec = {}
    for i in need:
        try:
            dec[i] = decode_norm(canon[i])
        except Exception:
            dec[i] = None
            rec["failed"] += 1
    for reg, (lo_i, hi_i, picks) in plan.items():
        cache_r = {}
        for j, i in enumerate(picks):
            a = dec[int(i)]
            if a is None:
                continue
            if int(i) not in cache_r:
                cache_r[int(i)] = crop_render(a, geo[reg]["box"], right)
            vols[reg][j] = cache_r[int(i)]
            masks[reg][j] = 1
        rec["regions"][reg] = {"lo_i": lo_i, "hi_i": hi_i, "real": hi_i - lo_i + 1, "unique": len(set(picks.tolist())),
                               "filled": int(masks[reg].sum())}
    return vols, masks, rec
